import java.util.*;
class Solution {
    public int getMaximumEvents(int[] payload) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int v : payload) cnt.merge(v, 1, Integer::sum);
        int s = 0;
        for (int v : cnt.values()) s += Math.min(v, 3);
        return s;
    }
}

class Solution {
public:
    int getMaximumEvents(vector<int>& payload) {
        unordered_map<int, int> cnt;
        for (int v : payload) cnt[v]++;
        int s = 0;
        for (auto& [k, v] : cnt) s += min(v, 3);
        return s;
    }
};
